-- ------------------------------------------------------------------------
-- 0010_reports_ordering.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Reports ordering. `public.reports` has no `created_at` column — the visit
-- history is ordered by `visit_at` (newest visit first), with the identity
-- `id` as the tiebreaker for rows that share a date or have none. These
-- indexes back that sort so the register and the per-call/per-UCN lookups
-- stay fast. Run in the Supabase SQL Editor as postgres.
-- ===========================================================================

create index if not exists reports_visit_at_idx on public.reports (visit_at desc nulls last, id desc);
-- reports_call_number_idx (call_number) was here; a prefix of reports_call_number_entry_idx.
-- Removed 2026-10-05; 0382 drops it where it exists.

-- ------------------------------------------------------------------------
-- 0071_report_source_ref.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Bulk report → call mapping: keep what a link was DERIVED FROM.
--
-- Reports recovered from an AppSheet export arrive carrying AppSheet file
-- references, not Drive links — `Reports_Images/foo.png`, or a
-- gettablefileurl?... URL. The import turns those into Drive links and stores
-- them in `manual_report`, which is what the app opens.
--
-- `source_ref` keeps the ORIGINAL reference alongside it. Without that, a link
-- that resolved to the wrong file is unprovable and unfixable: you cannot tell
-- what it was meant to point at, and a re-run has nothing to re-resolve from.
-- For a quality record that is the difference between a recoverable mistake and
-- a permanent one, which is why it is a column and not a note in `data`.
--
-- `mapped_at` says the row came in through the bulk mapping rather than from an
-- engineer in the field — so a recovered visit is never mistaken for one
-- reported live.
-- ===========================================================================

alter table public.reports add column if not exists source_ref text not null default '';
alter table public.reports add column if not exists mapped_at  timestamptz;

comment on column public.reports.source_ref is
  'The original AppSheet file reference this row''s manual_report was derived from. Kept so a wrong link can be re-resolved.';
comment on column public.reports.mapped_at is
  'Set when the row was loaded by the bulk report → call mapping, not reported live.';

-- The mapping looks a call up by UCN and by call number; both already have
-- their index (0002, 0010). This one is for finding what the bulk run touched.
create index if not exists reports_mapped_at_idx on public.reports (mapped_at desc) where mapped_at is not null;

-- ---------------------------------------------------------------------------
-- Make `uid` usable as an UPSERT target.
--
-- 0002 created it as a PARTIAL unique index (`where uid is not null`).
-- Postgres will not infer a partial index from a bare `on conflict (uid)`, so
-- the bulk mapping's upsert failed outright with "there is no unique or
-- exclusion constraint matching the ON CONFLICT specification" — which is what
-- makes re-running a recovery sheet correct its rows instead of doubling the
-- visit history.
--
-- A FULL unique index is equivalent here and does infer: NULLs are distinct in
-- a unique index, so the rows with no uid (the sheet-era ones) still coexist
-- exactly as they did under the partial index.
-- ---------------------------------------------------------------------------
create unique index if not exists reports_uid_uniq on public.reports (uid);
drop index if exists public.reports_uid_key;

-- ------------------------------------------------------------------------
-- 0115_visit_date_sanity.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- A VISIT CANNOT HAVE HAPPENED IN THE FUTURE, OR BEFORE THE COMPLAINT.
--
-- The user's two rules (2026-09-06), on the Visit Update form. Both are about a
-- visit that has not happened, rather than one recorded untidily:
--
--   1. NOT IN THE FUTURE. A call's status comes from its LATEST visit, so a
--      visit dated next week closes a call nobody has been to — and keeps it
--      closed until that day passes.
--   2. NOT BEFORE THE COMPLAINT. Nobody attended a fault that had not been
--      reported, and every response-time figure taken from the pair goes
--      negative.
--
-- The form enforces both. This is the same rule where it cannot be typed past:
-- `min`/`max` on a date input stop the PICKER, not a pasted value, and a visit
-- report is a quality record.
--
-- ---------------------------------------------------------------------------
-- WHAT IT DELIBERATELY DOES NOT JUDGE: HISTORY.
--
-- `reports` is also where the superseded system's visits live, and they must be
-- loadable exactly as they were — a file whose dates are imperfect is still the
-- record of what happened, and refusing it would leave the register with a gap
-- instead of an imperfection. That is the same exemption 0089 makes for
-- imported stock.
--
-- The signal is the row's own id, which each writer sets and none of them share:
--
--   WEB-…   the Visit Update form (saveReport)     -> CHECKED
--   IMP-…   Bulk Uploads, derived from call + date -> not checked
--   other   Bulk Report Mapping (carries source_ref), a restore, a migration
--                                                  -> not checked
--
-- So the rule governs what is ENTERED from today, and says nothing about what
-- was loaded. Widening it later is one line; it would want a look at the
-- existing data first, which is why it is not done here.
--
-- A call with NO complaint date is held to rule 1 only: there is nothing to
-- compare against, and refusing the visit would invent a requirement.
--
-- TIMEZONE, and why this is not `> now()`. The app writes the chosen calendar
-- day as UTC midnight (`2026-09-06T00:00:00Z`). Between midnight and 05:30 IST
-- that instant is still in the FUTURE relative to now(), so a plain `> now()`
-- would refuse a visit entered early in the morning and dated today. The
-- comparison is therefore between DAYS: the visit's own day (UTC, as written)
-- against today in India, which is where the business is.
-- ===========================================================================

create or replace function public.reports_visit_date_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_visit date; v_complaint date; v_today date;
begin
  if new.visit_at is null then return new; end if;

  -- Only what the Visit Update form writes. See the header.
  if coalesce(new.uid, '') !~ '^WEB-' then return new; end if;

  -- An UPDATE that leaves the date alone is not this trigger's business — a
  -- report corrected years later must not be blocked by a rule about when it
  -- was entered.
  if tg_op = 'UPDATE' and old.visit_at is not distinct from new.visit_at then
    return new;
  end if;

  v_visit := (new.visit_at at time zone 'UTC')::date;
  v_today := (now() at time zone 'Asia/Kolkata')::date;

  if v_visit > v_today then
    raise exception 'A visit cannot be dated in the future (% is after %)', v_visit, v_today
      using errcode = 'check_violation';
  end if;

  select c.complaint_date into v_complaint from public.calls c where c.ucn = new.ucn;
  if v_complaint is not null and v_visit < v_complaint then
    raise exception 'A visit cannot be dated before the complaint (% is before %)', v_visit, v_complaint
      using errcode = 'check_violation';
  end if;

  return new;
end $$;

drop trigger if exists reports_visit_date_guard on public.reports;
create trigger reports_visit_date_guard
  before insert or update on public.reports
  for each row execute function public.reports_visit_date_guard();

comment on function public.reports_visit_date_guard() is
  'A visit entered on the Visit Update form (uid WEB-...) cannot be dated in the future or before its call''s complaint date. Imported history is exempt by design — see the migration header.';

-- ------------------------------------------------------------------------
-- 0436_visit_date_from_breakdown.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0436 -- A VISIT MAY BE DATED FROM THE BREAKDOWN DATE TO TODAY (the user,
-- 2026-10-14: "Reports can allow a Dates between the Breakdown Date and
-- Today"; asked, the Visit Report's Visit Date).
--
-- reports_visit_date_guard() (0115) refused a visit dated before the call's
-- COMPLAINT DATE. A call registered from a request now carries the day the
-- request was RAISED as its Complaint Date and the day it was ATTENDED as its
-- Breakdown Date (0435), and an engineer is often there before the request is
-- raised -- so the lower bound is the Breakdown Date, falling back to the
-- Complaint Date where a call carries none. Everything else is 0115 as it was:
-- only the Visit Update form's rows (uid WEB-) are judged, never imported
-- history, and a correction that leaves the date alone is not checked.
-- ===========================================================================

create or replace function public.reports_visit_date_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_visit date; v_from date; v_today date;
begin
  if new.visit_at is null then return new; end if;

  -- Only what the Visit Update form writes. See 0115's header.
  if coalesce(new.uid, '') !~ '^WEB-' then return new; end if;

  -- An UPDATE that leaves the date alone is not this trigger's business.
  if tg_op = 'UPDATE' and old.visit_at is not distinct from new.visit_at then
    return new;
  end if;

  v_visit := (new.visit_at at time zone 'UTC')::date;
  v_today := (now() at time zone 'Asia/Kolkata')::date;

  if v_visit > v_today then
    raise exception 'A visit cannot be dated in the future (% is after %)', v_visit, v_today
      using errcode = 'check_violation';
  end if;

  select coalesce(c.breakdown_date, c.complaint_date) into v_from from public.calls c where c.ucn = new.ucn;
  if v_from is not null and v_visit < v_from then
    raise exception 'A visit cannot be dated before the breakdown (% is before %)', v_visit, v_from
      using errcode = 'check_violation';
  end if;

  return new;
end $$;

comment on function public.reports_visit_date_guard() is
  'A visit entered on the Visit Update form (uid WEB-...) cannot be dated in the future or before its call''s Breakdown Date (else Complaint Date) (0436). Imported history is exempt by design -- see 0115.';

-- ------------------------------------------------------------------------
-- 0224_solved_without_a_report.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- SOLVED, BUT NOBODY FILED THE REPORT.
--
--   The user, 2026-09-20: "Create a Report - Call is Solved, but Report or
--   Visit Entry is missing - View only for Admins and Super Admins."
--
-- This is the list that says WHICH visits to re-upload, and it exists because
-- the answer was previously "load them all again and hope".
--
-- THE FOUR GAPS ARE NOT THE SAME GAP, and a report that lumps them together
-- cannot be acted on — each needs a different fix:
--
--   no visit at all ....... the call has NO `reports` row. Nothing recorded
--                           that anybody attended. The visit must be loaded.
--   no visit date ......... a visit row with no `visit_at`. It cannot be
--                           placed in time, so it cannot date the call.
--   entry date is an ....... `reports.updated_at` is NOT NULL and DEFAULTS TO
--   import stamp            `now()`, so a file with no Visit Entry Date does
--                           not leave a blank — it silently takes the MOMENT
--                           OF THE IMPORT. A missing entry date therefore
--                           cannot be found by looking for a null, which is
--                           why this report looks for the signature instead:
--                           the number of visits sharing that timestamp TO THE
--                           MICROSECOND. Twenty-five visits genuinely entered
--                           at the same instant is not a thing that happens;
--                           a batch load is. The COUNT is published either way
--                           (`visits_sharing_entry_stamp`), so the reader sees
--                           the evidence and not only the verdict.
--                           It matters because that column decides a call's
--                           status — 0032 takes the LATEST ENTRY — so a whole
--                           batch sharing one stamp lets an arbitrary row
--                           decide every call in it.
--   no service report ..... no `manual_report`. The visit is recorded, the
--                           document behind it is not.
--
-- A call can be missing more than one, so `missing` lists every one of them
-- rather than the first — being told about a gap, fixing it, and being told
-- about the next one is three round trips for one row.
--
-- "SOLVED" INCLUDES "SOLVED - REPORT PENDING", AND THE ROW SAYS WHICH. They
-- are different findings: Report Pending is the system stating a known
-- absence, and a plain Solved with no report is the system contradicting
-- itself. Filtering to one of them would hide half the problem; merging them
-- without saying which would misrepresent it. `open_state` is carried through.
--
-- IT IS A `security_invoker` VIEW over `calls` and `reports`, so the call
-- policies decide the rows exactly as they do everywhere else. The SCREEN is
-- what is restricted to administrators (`mod:/missing-visit-reports`, below);
-- the view does not invent a second, different rule, which is how a screen and
-- its data come to disagree.
-- ===========================================================================
-- Dropped first: `create or replace view` can only APPEND a column, and this
-- definition inserts one in the middle. The view is new here, so nothing
-- depends on it and the drop is idempotent.
drop view if exists public.solved_without_report;
create view public.solved_without_report as
with latest as (
  -- THE LATEST ENTRY, not the latest visit date — the same ordering
  -- `sync_call_last_visit()` uses (0032), because this report is about what
  -- that function had to work with.
  select distinct on (r.ucn)
         r.ucn, r.visit_at, r.updated_at, r.manual_report, r.uid, r.engineer,
         count(*) over (partition by r.updated_at) as sharing
    from public.reports r
   order by r.ucn, r.updated_at desc nulls last, r.id desc
)
select
  c.ucn,
  c.call_number,
  c.reg_date,
  c.open_state,
  c.party_name,
  c.product_name,
  c.serial,
  c.state,
  c.last_visit_at,
  l.uid            as visit_uid,
  l.visit_at       as visit_date,
  l.updated_at     as visit_entry_date,
  l.sharing        as visits_sharing_entry_stamp,
  nullif(btrim(coalesce(l.manual_report, '')), '') as service_report,
  coalesce(nullif(btrim(coalesce(l.engineer, '')), ''), '') as visit_engineer,
  -- EVERY gap on the row, in the order they have to be fixed in.
  array_to_string(
    array_remove(array[
      case when l.ucn is null                                        then 'no visit at all' end,
      case when l.ucn is not null and l.visit_at is null             then 'no visit date' end,
      case when l.ucn is not null and l.sharing >= 25
             then 'entry date looks like an import stamp (' || l.sharing || ' visits share it)' end,
      case when l.ucn is not null
            and coalesce(btrim(l.manual_report), '') = ''            then 'no service report' end
    ], null), ' · ')                                                 as missing
from public.calls c
left join latest l on l.ucn = c.ucn
where coalesce(c.open_state, '') like 'Solved%'
  and (l.ucn is null
       or l.visit_at is null
       or l.sharing >= 25
       or coalesce(btrim(l.manual_report), '') = '');
alter view public.solved_without_report set (security_invoker = on);
grant select on public.solved_without_report to authenticated;
comment on view public.solved_without_report is
  'Calls reading Solved whose visit record is incomplete — no visit at all, no visit date, no visit entry date, or no service report. `missing` names every gap on the row. Administrators only, by the module key rather than by a rule of its own (0224).';

-- ---------------------------------------------------------------------------
-- THE KEY REACHES NOBODY WITHOUT THIS. `permsForRole()` is
-- `if (stored && stored.length) return stored;` — the code defaults apply ONLY
-- to a role whose stored set is EMPTY, and on a project in use every role has
-- a tuned row. So a new screen's key must be MERGED into `app_roles` or the
-- page is invisible to everybody with no error anywhere. 0195 and 0209 are the
-- pattern; this is the same shape.
--
-- ADMINISTRATORS ONLY: the three roles that see every module. MERGED, never
-- overwritten, and a role with ZERO permissions is left alone — an empty array
-- means "not configured" and writing one key into it turns the fallback off.
-- ---------------------------------------------------------------------------
do $$
declare n integer;
begin
  if to_regclass('public.app_roles') is null then return; end if;

  update public.app_roles ar
     set permissions = (
           select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
             from (
               select jsonb_array_elements_text(ar.permissions) as v
               union
               select unnest(array['mod:/missing-visit-reports']) as v
             ) u
         ),
         updated_at = now()
   where jsonb_array_length(ar.permissions) > 0
     and ar.role in ('admin', 'technical_support', 'zoho_migration')
     and not (ar.permissions ? 'mod:/missing-visit-reports');
  get diagnostics n = row_count;
  raise notice '0224: % of 3 role(s) given mod:/missing-visit-reports', n;
end $$;

-- ------------------------------------------------------------------------
-- 0486_visit_date_reads.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- VISIT DATE CHECK: what a model read on the manual report, kept, and the
-- Visit Date corrected from it on an administrator's say-so (the user,
-- 2026-11-17: "Lets do only Visit Date. Drop the UCN. If Haiku Fails then go
-- to Sonnet. And have a Mechanism to store the REsults back in Supabase DB and
-- Add it as a Report under Reports. And Also add a Provision for Admin [I will
-- change this later via Roles and Permission] to update the Visit Date in the
-- Actual Visit Record." -- and: "The Same records need not be re-run.")
--
-- 1. public.visit_date_reads -- ONE ROW PER VISIT (unique report_uid), so a
--    visit checked once is not checked again. Written ONLY by the Edge
--    Function read-report-box, as the service role: there is no insert,
--    update or delete policy, so a reading in this table is one a model
--    produced, not one somebody typed. A run where both models erred is NOT
--    stored, so that visit is tried again next time.
--    outcome: match (the date read is the visit's day in India time),
--    mismatch (a different day, or the visit has no date), unreadable
--    (neither model could read a date), no_box (the device found no Service
--    Visit Date box on the report, so nothing was sent -- stored so the visit
--    is not tried again; a report that could not be OPENED is not stored).
--
-- 2. public.visit_date_check -- the report: each reading beside the visit's
--    date as it stands NOW (it may have been corrected since).
--
-- 3. public.resolve_visit_date_read(id, apply) -- the administrator's
--    decision on a reading: APPLY moves the visit's Visit Date to the day read
--    (keeping its time of day; the Visit Entry Date, reports.updated_at, is
--    not touched), KEEP records that RITHI's date stands. Once only per
--    reading. The change to the visit is recorded by record_audit like any
--    other, and the reading keeps the old and new values.
--
-- PERMISSIONS: three new keys, granted to NO role here --
--   visitdate.view (the report), visitdate.check (send a cut-out to be read),
--   visitdate.fix (apply / keep).
-- An administrator passes has_perm() already, so "Admin only for now" needs
-- no grant; the keys are on Roles & Permissions to be ticked for other roles
-- when the user decides (the standing rule: Roles & Permissions are the
-- user's, not a migration's).
-- ===========================================================================

create table if not exists public.visit_date_reads (
  id bigint generated always as identity primary key,
  report_uid text not null,
  ucn text not null default '',
  recorded_visit_at timestamptz,
  read_date date,
  read_as_written text,
  notes text not null default '',
  outcome text not null check (outcome in ('match', 'mismatch', 'unreadable', 'no_box')),
  model text not null default '',
  tried text[] not null default '{}',
  first_error text not null default '',
  ms integer not null default 0,
  input_tokens integer not null default 0,
  output_tokens integer not null default 0,
  cost_usd numeric(12, 6) not null default 0,
  read_by uuid,
  created_at timestamptz not null default now(),
  resolution text check (resolution in ('applied', 'kept')),
  resolved_by uuid,
  resolved_at timestamptz,
  old_visit_at timestamptz,
  new_visit_at timestamptz
);

create unique index if not exists visit_date_reads_report_uid on public.visit_date_reads (report_uid);
create index if not exists visit_date_reads_created on public.visit_date_reads (created_at desc, id desc);

comment on table public.visit_date_reads is
  'Visit Date Check (0486): the Service Visit Date a model read on a visit''s manual report, one row per visit, written only by the Edge Function read-report-box; resolution set only by resolve_visit_date_read().';

alter table public.visit_date_reads enable row level security;

drop policy if exists visit_date_reads_read on public.visit_date_reads;
create policy visit_date_reads_read on public.visit_date_reads
  for select using ((select public.has_perm('visitdate.view')));

grant select on public.visit_date_reads to authenticated;
revoke insert, update, delete on public.visit_date_reads from anon, authenticated;

-- The report: each reading with the visit as it stands now.
create or replace view public.visit_date_check
with (security_invoker = on) as
select v.id,
       v.created_at as checked_at,
       v.report_uid,
       v.ucn,
       r.engineer,
       r.call_status,
       v.recorded_visit_at,
       r.visit_at as current_visit_at,
       v.read_date,
       v.read_as_written,
       v.outcome,
       v.notes,
       v.model,
       v.tried,
       v.first_error,
       v.ms,
       v.input_tokens,
       v.output_tokens,
       v.cost_usd,
       v.resolution,
       v.resolved_at,
       rb.full_name as resolved_by_name,
       v.old_visit_at,
       v.new_visit_at,
       r.manual_report
  from public.visit_date_reads v
  left join public.reports r on r.uid = v.report_uid
  left join public.profiles rb on rb.id = v.resolved_by;

grant select on public.visit_date_check to authenticated;

-- The administrator's decision on one reading.
create or replace function public.resolve_visit_date_read(p_id bigint, p_apply boolean)
returns text language plpgsql security definer set search_path = public as $$
declare
  r public.visit_date_reads;
  v_old timestamptz;
  v_new timestamptz;
  v_today date := (now() at time zone 'Asia/Kolkata')::date;
begin
  if not coalesce(public.has_perm('visitdate.fix'), false) then
    raise exception 'Only an administrator may correct a Visit Date from a report reading'
      using errcode = 'insufficient_privilege';
  end if;

  select * into r from public.visit_date_reads where id = p_id for update;
  if not found then
    raise exception 'No such reading (%).', p_id using errcode = 'no_data_found';
  end if;
  if r.resolution is not null then
    raise exception 'This reading was already %.',
      case r.resolution when 'applied' then 'applied to the visit' else 'kept as recorded' end
      using errcode = 'check_violation';
  end if;

  if not p_apply then
    update public.visit_date_reads
       set resolution = 'kept', resolved_by = auth.uid(), resolved_at = now()
     where id = p_id;
    return 'kept';
  end if;

  if r.read_date is null then
    raise exception 'The reading has no date to apply.' using errcode = 'check_violation';
  end if;
  if r.read_date > v_today then
    raise exception 'The date read (%) is in the future -- not applied.', to_char(r.read_date, 'DD-Mon-YYYY')
      using errcode = 'check_violation';
  end if;

  select visit_at into v_old from public.reports where uid = r.report_uid for update;
  if not found then
    raise exception 'The visit % no longer exists.', r.report_uid using errcode = 'no_data_found';
  end if;

  -- Move the DAY, keep the time of day: the visit's own clock time is not
  -- what was read, and is not changed. A visit with no date gets the day read
  -- at midnight India time.
  if v_old is null then
    v_new := r.read_date::timestamp at time zone 'Asia/Kolkata';
  else
    v_new := v_old + ((r.read_date - (v_old at time zone 'Asia/Kolkata')::date) * interval '1 day');
  end if;

  -- reports.updated_at is the Visit Entry Date and is deliberately left alone.
  update public.reports set visit_at = v_new where uid = r.report_uid;

  update public.visit_date_reads
     set resolution = 'applied', resolved_by = auth.uid(), resolved_at = now(),
         old_visit_at = v_old, new_visit_at = v_new
   where id = p_id;
  return 'applied';
end $$;

revoke execute on function public.resolve_visit_date_read(bigint, boolean) from public, anon;
grant execute on function public.resolve_visit_date_read(bigint, boolean) to authenticated;

-- Every reading and every decision on one is recorded (0048's record_audit).
do $$
begin
  if to_regprocedure('public.record_audit_fn()') is not null then
    drop trigger if exists record_audit_i on public.visit_date_reads;
    drop trigger if exists record_audit_u on public.visit_date_reads;
    create trigger record_audit_i after insert on public.visit_date_reads
      referencing new table as new_rows for each statement execute function public.record_audit_fn();
    create trigger record_audit_u after update on public.visit_date_reads
      referencing old table as old_rows new table as new_rows for each statement execute function public.record_audit_fn();
  end if;
end $$;

-- The five system columns every table carries (0244), attached now: sys_columns
-- runs LAST in a fresh apply, but on the live project it has already run.
do $$
begin
  if to_regprocedure('public.sys_columns_attach(regclass)') is not null then
    perform public.sys_columns_attach('public.visit_date_reads'::regclass);
